package com.ptms.service;import com.ptms.dto.SettingsDto;import org.junit.jupiter.api.Test;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;class TicketCombinationServiceTest{@Test void minimumCombination(){SettingsService s=mock(SettingsService.class);when(s.get()).thenReturn(new SettingsDto("06:00","12:00","06:00","12:30",0,"1,2,4,6,8,12"));var r=new TicketCombinationService(s).combinationsFor(14);assertThat(r).contains(List.of(12,2));assertThat(r).allSatisfy(x->assertThat(x).hasSize(2));}}
